{
  "API_calls": [],
  "collected_information": {
    "programming_language": "Python >=3.10 and <3.14",
    "dependencies": {
      "main_package": "crewai (pip install crewai)",
      "optional_extras": {
        "tools": "pip install 'crewai[tools]'",
        "embeddings": "pip install 'crewai[embeddings]'"
      },
      "notes": [
        "Rust compiler required for some dependencies (e.g., tiktoken)",
        "Windows users should install Visual C++ Build Tools",
        "Upgrade pip if build issues occur with: pip install --upgrade pip"
      ]
    },
    "environment_variables": {
      "file": ".env",
      "variables": [
        "OPENAI_API_KEY=sk-...",
        "SERPER_API_KEY=YOUR_KEY_HERE",
        "OTEL_SDK_DISABLED=true (optional to disable telemetry)"
      ]
    },
    "dependency_management": {
      "tool": "uv",
      "commands": [
        "uv lock (lock dependencies)",
        "uv sync (install dependencies)",
        "uv venv (create virtual environment)"
      ]
    },
    "pre_commit": "pre-commit install",
    "installation": {
      "basic": "pip install crewai",
      "with_tools": "pip install 'crewai[tools]'",
      "local_build": "pip install dist/*.tar.gz"
    },
    "tests": {
      "framework": "pytest",
      "run_all": "uv run pytest .",
      "run_individual": "pytest tests/cli/test_create_crew.py"
    },
    "project_run": [
      "crewai run",
      "python src/my_project/main.py"
    ],
    "additional_commands": [
      "uvx mypy src (static typing checks)",
      "uv build (packaging)"
    ],
    "prerequisites": [
      "Python 3.10 to <3.14 installed",
      "Rust compiler installed",
      "Visual C++ Build Tools on Windows"
    ]
  },
  "terminate": true
}
